/** Sales confirmation (T-006).
 *
 *  Once the masters exist, a sales confirmation is sent to the supplier on the
 *  buyer's behalf and a copy goes to the buyer. The number and the date/time are
 *  generated by the database when the record is created and can never be edited.
 *  A confirmation is "complete" when both parties and both of their companies,
 *  the count, the ex-mill quantity, the UOM, freight and (for BAGS) the bag
 *  weight are filled in; only then do "SMS Supplier" and "SMS Buyer" appear.
 *
 *  Each button sends to one party only, over Email and/or WhatsApp (both
 *  optional). No messaging provider is connected yet, so a send opens the
 *  prefilled WhatsApp chat and the prefilled email for the person to press Send,
 *  and the screen records that it was done (see lib/integrations.ts). */

import { useCallback, useEffect, useMemo, useState } from 'react'
import { supabase } from '../lib/supabase'
import type { CountRow, PaymentTerm } from '../api/types'
import { useAuth } from '../auth/AuthProvider'
import { Loading } from '../components/Loading'
import { ImportIssues, ListTools, useSelection } from '../components/ListTools'
import { bulkDelete, deleteSummary } from '../lib/bulk'
import { downloadCSV, toCSV } from '../lib/csv'
import { errMessage } from '../lib/party'
import { formatDateTime } from '../lib/format'
import { ConfirmationDrawer } from '../components/sc/ConfirmationDrawer'
import { BulkSendDrawer } from '../components/sc/BulkSendDrawer'
import { num } from '../components/sc/scShared'
import type { Company, Party, ScRow } from '../components/sc/scShared'

const CSV_COLUMNS = [
  'sc_no', 'confirmed_at', 'status', 'supplier', 'supplier_company', 'buyer', 'buyer_company', 'count',
  'quantity', 'net_quantity', 'uom', 'bag_weight', 'freight', 'price_basis', 'rate', 'buyer_rate', 'supplier_rate', 'commission_type', 'commission_value', 'delivery_schedule', 'special_instructions', 'execution_status', 'remarks',
] as const

export default function ScRows() {
  const { can } = useAuth()
  const canManage = can('sc.manage')
  const canRead = canManage || can('sc.read')
  const [rows, setRows] = useState<ScRow[] | null>(null)
  const [suppliers, setSuppliers] = useState<Party[]>([])
  const [buyers, setBuyers] = useState<Party[]>([])
  const [companies, setCompanies] = useState<Company[]>([])
  const [counts, setCounts] = useState<CountRow[]>([])
  const [terms, setTerms] = useState<PaymentTerm[]>([])
  const [editing, setEditing] = useState<ScRow | 'new' | null>(null)
  const [search, setSearch] = useState('')
  const [banner, setBanner] = useState<{ kind: 'ok' | 'bad'; text: string } | null>(null)
  const [busy, setBusy] = useState(false)
  const [exec, setExec] = useState<Map<string, { exec_status: string; dispatched_qty: number }>>(new Map())
  const [bulk, setBulk] = useState(false)

  const load = useCallback(async () => {
    const [r, s, b, c, k, t, ex] = await Promise.all([
      supabase.from('sales_confirmations').select('*').order('confirmed_at', { ascending: false }),
      supabase.from('supplier_master').select('id,name,mobile,email,company_id,is_active').order('name'),
      supabase.from('buyer_master').select('id,name,mobile,email,company_id,is_active').order('name'),
      supabase.from('companies').select('id,name,is_active').order('name'),
      supabase.from('count_master').select('*').order('count_no').order('display_name'),
      supabase.from('payment_terms').select('*').order('name'),
      supabase.rpc('sc_execution_statuses'),
    ])
    setExec(new Map(((ex.data ?? []) as { sc_id: string; exec_status: string; dispatched_qty: number }[]).map((x) => [x.sc_id, x])))
    if (r.error) setBanner({ kind: 'bad', text: errMessage(r.error, 'Could not load sales confirmations') })
    setRows((r.data ?? []) as ScRow[])
    setSuppliers((s.data ?? []) as Party[])
    setBuyers((b.data ?? []) as Party[])
    setCompanies((c.data ?? []) as Company[])
    setCounts((k.data ?? []) as CountRow[])
    setTerms((t.data ?? []) as PaymentTerm[])
  }, [])
  useEffect(() => {
    void load()
  }, [load])

  const nm = (list: { id: string; name: string }[]) => new Map(list.map((x) => [x.id, x.name]))
  const supplierName = useMemo(() => nm(suppliers), [suppliers])
  const buyerName = useMemo(() => nm(buyers), [buyers])
  const companyName = useMemo(() => nm(companies), [companies])
  const countName = useMemo(() => new Map(counts.map((x) => [x.id, x.display_name])), [counts])

  const shown = useMemo(() => {
    const q = search.trim().toLowerCase()
    return (rows ?? []).filter(
      (x) =>
        !q ||
        x.sc_no.toLowerCase().includes(q) ||
        (x.supplier_id ? supplierName.get(x.supplier_id) ?? '' : '').toLowerCase().includes(q) ||
        (x.buyer_id ? buyerName.get(x.buyer_id) ?? '' : '').toLowerCase().includes(q) ||
        (x.count_id ? countName.get(x.count_id) ?? '' : '').toLowerCase().includes(q),
    )
  }, [rows, search, supplierName, buyerName, countName])

  const selection = useSelection(useMemo(() => shown.map((x) => x.id), [shown]))

  async function deleteSelected() {
    setBusy(true)
    setBanner(null)
    const names = new Map((rows ?? []).map((x) => [x.id, x.sc_no]))
    const result = await bulkDelete('sales_confirmations', selection.chosen)
    setBanner(deleteSummary('confirmation', 'confirmations', result, (id) => names.get(id) ?? id))
    selection.clear()
    await load()
    setBusy(false)
  }

  function exportCSV() {
    const list = (selection.chosen.length > 0 ? shown.filter((x) => selection.isSelected(x.id)) : shown).map((x) => ({
      ...x,
      supplier: x.supplier_id ? supplierName.get(x.supplier_id) ?? '' : '',
      buyer: x.buyer_id ? buyerName.get(x.buyer_id) ?? '' : '',
      supplier_company: x.supplier_company_id ? companyName.get(x.supplier_company_id) ?? '' : '',
      buyer_company: x.buyer_company_id ? companyName.get(x.buyer_company_id) ?? '' : '',
      count: x.count_id ? countName.get(x.count_id) ?? '' : '',
      execution_status: exec.get(x.id)?.exec_status ?? '',
    }))
    downloadCSV(`sales-confirmations-${new Date().toISOString().slice(0, 10)}.csv`, toCSV(CSV_COLUMNS, list))
  }

  if (!canRead) return <div className="card pad narrow-card">Your account does not have access to sales confirmations.</div>
  if (!rows) return <Loading label="Loading sales confirmations" />

  const execChip = (v: string | undefined) =>
    !v ? <span className="muted">—</span> : <span className={`chip${v === 'Executed' ? ' good' : v === 'Cancelled' ? ' bad' : v === 'Open' ? '' : ' warn'}`}>{v}</span>

  const statusChip = (x: ScRow) =>
    x.status === 'confirmed' ? <span className="chip good">Confirmed</span> : x.status === 'cancelled' ? <span className="chip bad">Cancelled</span> : <span className="chip warn">Draft</span>

  return (
    <>
      <header className="page-head">
        <div>
          <h1>Sales confirmations</h1>
          <p className="page-sub">Confirmations sent to the supplier on the buyer's behalf, with a copy to the buyer.</p>
        </div>
        {canManage && (
          <button className="btn primary" type="button" onClick={() => setEditing('new')}>
            New sales confirmation
          </button>
        )}
      </header>

      {banner && (
        <div className={banner.kind === 'ok' ? 'notice' : 'alert'} role="status">
          {banner.text}
          <button className="btn ghost sm" type="button" onClick={() => setBanner(null)}>
            Dismiss
          </button>
        </div>
      )}

      <ListTools
        plural="confirmations"
        canImport={false}
        canDelete={canManage}
        selectedCount={selection.chosen.length}
        exportLabel={`Export ${selection.chosen.length > 0 ? `${selection.chosen.length} selected` : shown.length === rows.length ? 'all' : `${shown.length} shown`} as CSV`}
        exportDisabled={shown.length === 0}
        busy={busy}
        onImport={() => undefined}
        onExport={exportCSV}
        onDelete={deleteSelected}
      />
      <ImportIssues results={null} />
      {canManage && (
        <div style={{ marginBottom: 12 }}>
          <button className="btn primary" type="button" disabled={selection.chosen.length === 0} onClick={() => setBulk(true)}>
            Send {selection.chosen.length > 0 ? `${selection.chosen.length} selected` : 'selected'} confirmation{selection.chosen.length === 1 ? '' : 's'}
          </button>
          {selection.chosen.length === 0 && <span className="muted small"> Tick the confirmations to send, then choose who gets them.</span>}
        </div>
      )}

      <div className="field" style={{ maxWidth: 360 }}>
        <input aria-label="Search sales confirmations" placeholder="Search by no., supplier, buyer or count" value={search} onChange={(e) => setSearch(e.target.value)} />
      </div>

      {shown.length === 0 ? (
        <div className="card pad empty">{rows.length === 0 ? 'No sales confirmations yet.' : 'No confirmation matches that search.'}</div>
      ) : (
        <div className="table-wrap">
          <table>
            <thead>
              <tr>
                {canManage && (
                  <th style={{ width: 32 }}>
                    <input type="checkbox" checked={selection.allSelected} onChange={selection.toggleAll} aria-label="Select all" />
                  </th>
                )}
                <th>No.</th>
                <th>Date and time</th>
                <th>Supplier</th>
                <th>Buyer</th>
                <th>Count</th>
                <th className="right">Ex-mill qty</th>
                <th className="right">Net qty</th>
                <th>Freight</th>
                <th>Status</th>
                <th>Execution</th>
                <th>Sent to</th>
              </tr>
            </thead>
            <tbody>
              {shown.map((x) => (
                <tr key={x.id} className="clickable" onClick={() => setEditing(x)}>
                  {canManage && (
                    <td onClick={(e) => e.stopPropagation()}>
                      <input type="checkbox" checked={selection.isSelected(x.id)} onChange={() => selection.toggle(x.id)} aria-label={`Select ${x.sc_no}`} />
                    </td>
                  )}
                  <td className="mono">{x.sc_no}</td>
                  <td className="mono small">{formatDateTime(x.confirmed_at)}</td>
                  <td className="small">{x.supplier_id ? supplierName.get(x.supplier_id) ?? '—' : '—'}</td>
                  <td className="small">{x.buyer_id ? buyerName.get(x.buyer_id) ?? '—' : '—'}</td>
                  <td className="small">{x.count_id ? countName.get(x.count_id) ?? '—' : '—'}</td>
                  <td className="right mono">{x.quantity === null ? '—' : `${num(x.quantity)} ${x.uom}`}</td>
                  <td className="right mono">{x.net_quantity === null ? '—' : `${num(x.net_quantity)} ${x.uom}`}</td>
                  <td className="small">{x.freight === 'included' ? 'Included' : 'Excluded'}</td>
                  <td>{statusChip(x)}</td>
                  <td>{execChip(exec.get(x.id)?.exec_status)}</td>
                  <td className="small">
                    {x.supplier_notified_at && <span className="chip">Supplier</span>}
                    {x.buyer_notified_at && (
                      <span className="chip" style={x.supplier_notified_at ? { marginLeft: 6 } : undefined}>
                        Buyer
                      </span>
                    )}
                    {!x.supplier_notified_at && !x.buyer_notified_at && <span className="muted">—</span>}
                  </td>
                </tr>
              ))}
            </tbody>
          </table>
        </div>
      )}

      {editing && (
        <ConfirmationDrawer
          key={editing === 'new' ? 'new' : editing.id}
          sc={editing === 'new' ? null : editing}
          canManage={canManage}
          suppliers={suppliers}
          buyers={buyers}
          companies={companies}
          counts={counts}
          terms={terms}
          onClose={() => setEditing(null)}
          onDone={async (text, keepOpenId) => {
            setBanner({ kind: 'ok', text })
            await load()
            if (keepOpenId) {
              const { data } = await supabase.from('sales_confirmations').select('*').eq('id', keepOpenId).single()
              if (data) {
                setEditing(data as ScRow)
                return
              }
            }
            setEditing(null)
          }}
        />
      )}

      {bulk && (
        <BulkSendDrawer
          rows={(rows ?? []).filter((x) => selection.isSelected(x.id))}
          suppliers={suppliers}
          buyers={buyers}
          companies={companies}
          counts={counts}
          terms={terms}
          onClose={() => setBulk(false)}
          onChanged={load}
        />
      )}
    </>
  )
}